-- Reference data only. Does not enable brands for Create Build or add models/parts.
begin;
create table if not exists public.car_brand_reference (
  id text primary key, slug text unique not null, name text not null,
  details jsonb not null, collected_at timestamptz not null
);
alter table public.car_brand_reference enable row level security;
revoke all on public.car_brand_reference from anon, authenticated;
grant all on public.car_brand_reference to service_role;

-- Replace only this reference catalog; accounts, models and builds are untouched.
delete from public.car_brand_reference where id not in ('aion', 'bmw', 'byd', 'changan', 'deepal', 'denza', 'ferrari', 'ford', 'great-wall', 'haval', 'honda', 'isuzu', 'jaecoo', 'lamborghini', 'mazda', 'mercedes-benz', 'mg', 'mitsubishi', 'neta', 'nissan', 'omoda', 'ora', 'porsche', 'subaru', 'suzuki', 'toyota', 'xpeng', 'zeekr');
commit;
